hl.config({
  input = {
    -- Right Alt is Compose. Caps Lock goes back to Caps Lock
    -- (Omarchy default uses Caps Lock as Compose).
    kb_options = "compose:ralt",

    -- Natural (inverse) scrolling on mouse wheel: content follows the wheel.
    natural_scroll = true,

    touchpad = {
      -- Natural (inverse) scrolling on a trackpad, if one is connected later.
      natural_scroll = true,
    },
  },
})
